/* Implementation of method optional_release for managed value. */
AFW_DECLARE_STATIC(void)
impl_afw_value_managed_optional_release(
    const afw_value_t *instance,
    afw_xctx_t *xctx)
{
    afw_value_relaxedJson_managed_t *self =
        (afw_value_relaxedJson_managed_t *)instance;

    if (self->reference_count == 0) {
        return;
    }
    self->reference_count--;
    if (self->reference_count == 0) {
        afw_pool_free_memory(self->p, self,
            sizeof(afw_value_relaxedJson_managed_t) + self->internal.len, xctx);
    }
}

/* Implementation of method optional_release for unmanaged value. */
AFW_DECLARE_STATIC(void)
impl_afw_value_unmanaged_optional_release(
    const afw_value_t *instance,
    afw_xctx_t *xctx)
{
    (void)instance;
    AFW_THROW_ERROR_Z(general,
        "release of unmanaged scalar", xctx);
}

/* Implementation of method get_reference for unmanaged value. */
AFW_DECLARE_STATIC(const afw_value_t *)
impl_afw_value_get_reference(
    const afw_value_t *instance,
    afw_xctx_t *xctx)
{
    (void)instance;
    AFW_THROW_ERROR_Z(general,
        "get_reference of unmanaged scalar", xctx);
}

/* Slot fill: promote to managed in p->managed_p. */
AFW_DECLARE_STATIC(const afw_value_t *)
impl_afw_value_get_assignable_value(
    const afw_value_t *instance,
    const afw_pool_t *p,
    afw_xctx_t *xctx)
{
    const afw_value_relaxedJson_t *self =
        (const afw_value_relaxedJson_t *)instance;

    return afw_value_relaxedJson_create_managed(
        &self->internal, p, xctx);
}


/* Implementation of method get_reference for managed value. */
AFW_DECLARE_STATIC(const afw_value_t *)
impl_afw_value_managed_get_reference(
    const afw_value_t *instance,
    afw_xctx_t *xctx)
{
    afw_value_relaxedJson_managed_t *self =
        (afw_value_relaxedJson_managed_t *)instance;

    (void)xctx;
    self->reference_count++;
    return instance;
}


/* Implementation of method optional_release for managed slice. */
AFW_DECLARE_STATIC(void)
impl_afw_value_managed_slice_optional_release(
    const afw_value_t *instance,
    afw_xctx_t *xctx)
{
    afw_value_relaxedJson_managed_slice_t *self =
        (afw_value_relaxedJson_managed_slice_t *)instance;

    if (self->reference_count == 0) {
        return;
    }
    self->reference_count--;
    if (self->reference_count == 0) {
        if (self->containing_value) {
            afw_value_release(&self->containing_value->pub, xctx);
        }
        afw_pool_free_memory(self->p, self,
            sizeof(afw_value_relaxedJson_managed_slice_t), xctx);
    }
}

/* Implementation of method get_reference for managed slice. */
AFW_DECLARE_STATIC(const afw_value_t *)
impl_afw_value_managed_slice_get_reference(
    const afw_value_t *instance,
    afw_xctx_t *xctx)
{
    afw_value_relaxedJson_managed_slice_t *self =
        (afw_value_relaxedJson_managed_slice_t *)instance;

    (void)xctx;
    self->reference_count++;
    return instance;
}


